const correctedCopy = (
  owner: string,
  field: string,
  fallback: string,
): string => REVIEWED_COPY_CORRECTIONS[`${owner}.${field}`] ?? fallback;

const applyReviewedCopy = (screen: TScreenContract): TScreenContract => ({
  ...screen,
  displayTitle: correctedCopy(screen.code, 'displayTitle', screen.displayTitle),
  actor: correctedCopy(screen.code, 'actor', screen.actor),
  primaryAction: correctedCopy(
    screen.code,
    'primaryAction',
    screen.primaryAction,
  ),
  safeExit: correctedCopy(screen.code, 'safeExit', screen.safeExit),
  components: screen.components.map((component) => {
    const owner = `${screen.code}/${component.id}`;
    return {
      ...component,
      label: correctedCopy(owner, 'label', component.label),
      type: correctedCopy(owner, 'type', component.type),
      requirement: correctedCopy(owner, 'requirement', component.requirement),
      validation: correctedCopy(owner, 'validation', component.validation),
      binding: correctedCopy(owner, 'binding', component.binding),
    };
  }),
});

