const freezeComponent = (component: TScreenComponent): TScreenComponent =>
  Object.freeze({ ...component, states: Object.freeze([...component.states]) });
const freezeScreen = (screen: TScreenContract): TScreenContract =>
  Object.freeze({
    ...screen,
    states: Object.freeze([...screen.states]),
    components: Object.freeze(screen.components.map(freezeComponent)),
  });
export const SCREEN_CONTRACTS: readonly TScreenContract[] = Object.freeze(
  SCREEN_CONTRACT_SNAPSHOT.map(applyReviewedCopy).map(freezeScreen),
);
const SURFACES = new Set<TSurface>(['storefront', 'vendor', 'admin']);
const LAYOUT_RECIPES = new Set<TLayoutRecipe>([
  'dashboard',
  'form',
  'list',
  'detail',
  'composer',
  'viewer',
  'evidence',
  'reconciliation',
]);
const REGIONS = new Set<TScreenComponent['region']>([
  'header',
  'primary',
  'secondary',
  'aside',
  'footer',
]);
const SCREEN_STATES = new Set<TScreenState>(
  Object.keys(SCREEN_STATE_LABELS) as TScreenState[],
);
const SCREEN_CODE_PATTERN = /^MH-(?:00[1-9]|0[1-4]\d|05\d)$/;
const UI_PAGE_KEY_PATTERN = /^3-(?:0[1-9]|1[0-2])-ui$/;
const LOGICAL_ROUTE_PATTERN =
  /^\/(?!.*(?:\\|\/\/))[A-Za-z0-9._~!$&'()*+,;=:@%[\]/-]+$/;
const COMPONENT_ID_PATTERN = /^(?:A|D|F)\d{2}$/;
const SCREEN_TEXT_FIELDS = [
  'title',
  'displayTitle',
  'actor',
  'primaryAction',
  'safeExit',
] as const;
const COMPONENT_TEXT_FIELDS = [
  'label',
  'type',
  'requirement',
  'validation',
  'binding',
] as const;
const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null;
export const auditScreenContractRuntime = (
  contracts: readonly unknown[],
): string[] => {
  const errors: string[] = [];
  for (const value of contracts) {
    if (!isRecord(value)) {
      errors.push('unknown/contract: invalid');
      continue;
    }
    const code = typeof value.code === 'string' ? value.code : 'unknown';
    if (!SCREEN_CODE_PATTERN.test(code)) errors.push(`${code}/code: ${code}`);
    if (
      typeof value.pageKey !== 'string' ||
      !UI_PAGE_KEY_PATTERN.test(value.pageKey)
    )
      errors.push(`${code}/pageKey: ${String(value.pageKey)}`);
    if (
      typeof value.route !== 'string' ||
      !LOGICAL_ROUTE_PATTERN.test(value.route)
    )
      errors.push(`${code}/route: ${String(value.route)}`);
    for (const field of SCREEN_TEXT_FIELDS)
      if (typeof value[field] !== 'string' || value[field].trim().length === 0)
        errors.push(`${code}/${field}: empty`);
    if (!SURFACES.has(value.surface as TSurface))
      errors.push(`${code}/surface: ${String(value.surface)}`);
    if (!LAYOUT_RECIPES.has(value.layoutRecipe as TLayoutRecipe))
      errors.push(`${code}/layoutRecipe: ${String(value.layoutRecipe)}`);
    const screenStates = new Set<TScreenState>();
    const canAuditStateOwnership =
      Array.isArray(value.states) &&
      value.states.length > 0 &&
      value.states.every((state) => SCREEN_STATES.has(state as TScreenState));
    if (!Array.isArray(value.states)) errors.push(`${code}/states: invalid`);
    else if (value.states.length === 0) errors.push(`${code}/states: empty`);
    else
      for (const state of value.states)
        if (!SCREEN_STATES.has(state as TScreenState))
          errors.push(`${code}/state: ${String(state)}`);
        else screenStates.add(state as TScreenState);
    if (!Array.isArray(value.components)) {
      errors.push(`${code}/components: invalid`);
      continue;
    }
    if (value.components.length === 0) {
      errors.push(`${code}/components: empty`);
      continue;
    }
    for (const cv of value.components) {
      if (!isRecord(cv)) {
        errors.push(`${code}/unknown/component: invalid`);
        continue;
      }
      const id = typeof cv.id === 'string' ? cv.id : 'unknown';
      if (!COMPONENT_ID_PATTERN.test(id))
        errors.push(`${code}/${id}/id: ${id}`);
      if (
        typeof cv.annotationCode !== 'string' ||
        !COMPONENT_ID_PATTERN.test(cv.annotationCode) ||
        cv.annotationCode !== id
      )
        errors.push(
          `${code}/${id}/annotationCode: ${String(cv.annotationCode)}`,
        );
      for (const field of COMPONENT_TEXT_FIELDS)
        if (typeof cv[field] !== 'string' || cv[field].trim().length === 0)
          errors.push(`${code}/${id}/${field}: empty`);
      if (!REGIONS.has(cv.region as TScreenComponent['region']))
        errors.push(`${code}/${id}/region: ${String(cv.region)}`);
      if (!Array.isArray(cv.states))
        errors.push(`${code}/${id}/states: invalid`);
      else if (cv.states.length === 0)
        errors.push(`${code}/${id}/states: empty`);
      else
        for (const state of cv.states)
          if (!SCREEN_STATES.has(state as TScreenState))
            errors.push(`${code}/${id}/state: ${String(state)}`);
          else if (
            canAuditStateOwnership &&
            !screenStates.has(state as TScreenState)
          )
            errors.push(`${code}/${id}/state-not-owned: ${String(state)}`);
    }
  }
  return errors;
};
